import re, hashlib, json
f="/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev/646bc8ac-afb6-41b4-8d24-dcbaf28144cd/scratchpad/turns_chunk09.txt"
lines=open(f,encoding='utf-8',errors='replace').read().split("\n")
sessions=[]; cur=None
i=0
while i < len(lines):
    L=lines[i]
    if L.startswith("### [") and "—" in L:
        cur={"hdr":L.strip(),"turns":[]}
        sessions.append(cur); i+=1; continue
    m=re.match(r"^--- turn (\d+) ---$", L)
    if m and cur is not None:
        n=int(m.group(1)); body=[]; i+=1
        while i < len(lines):
            if re.match(r"^--- turn \d+ ---$", lines[i]) or lines[i].startswith("====") or lines[i].startswith("### ["):
                break
            body.append(lines[i]); i+=1
        cur["turns"].append((n,"\n".join(body).strip()))
        continue
    i+=1
seen={}
out=[]
for s in sessions:
    for (n,body) in s["turns"]:
        norm=re.sub(r"\s+"," ",body).strip().lower()
        h=hashlib.md5(norm.encode()).hexdigest()
        if h in seen:
            seen[h]["dupes"]+=1
            continue
        rec={"hdr":s["hdr"],"turn":n,"body":body,"dupes":0}
        seen[h]=rec; out.append(rec)
print(f"sessions={len(sessions)} total_turns={sum(len(s['turns']) for s in sessions)} unique={len(out)}")
json.dump(out, open("unique_turns.json","w"))
EOF
